let guide=[], current=-1, query='';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let completed=[];try{completed=JSON.parse(localStorage.getItem('guide-completed')||'[]');if(!Array.isArray(completed))completed=[];if(localStorage.getItem('guide-theme')==='dark')document.body.classList.add('dark')}catch{}
const groups=[['Start here',0,5],['Set up your workflow',5,15],['Work with agents',15,22],['Connect & automate',22,28],['Keep it close',28,35]];
function nav(){let html='';for(const [name,a,b]of groups){html+=`<p class="eyebrow" style="padding:20px 12px 5px;font-size:9px">${name}</p>`;for(let i=a;i<b;i++)html+=`<a href="#chapter-${i+1}" class="${current===i?'active':''}" ${current===i?'aria-current="page"':''}><span class="num">${completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${esc(guide[i].title)}</span></a>`}$('#chapters').innerHTML=html;$('#progressCount').textContent=`${completed.length} / ${guide.length}`;$('#progress').style.width=completed.length/guide.length*100+'%'}
function card(i){let c=guide[i];return `<a class="card" href="#chapter-${i+1}"><small>${String(i+1).padStart(2,'0')} / ${c.start===c.end?'PAGE '+c.start:'PAGES '+c.start+'–'+c.end} <span style="float:right">↗</span></small><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p></a>`}
const foot='<footer>Adapted from Claude_Code_Guide.pdf. Source examples are presented for reference.<br>Commands and experimental features may vary by version, platform, plan, and environment.</footer>';
function home(){current=-1;$('#main').innerHTML=`<section class="hero"><div class="kicker">A PRACTICAL FIELD GUIDE</div><h1>Less guessing.<br>More <em>building.</em></h1><p class="lead">Find your way around Claude Code. A hands-on guide to the commands, context, and workflows you’ll use while building real software.</p><div class="actions"><a class="primary" href="#chapter-1">Start reading <span>→</span></a><a class="secondary" href="#chapter-33">Find the right command ↗</a></div><div class="stats"><div><b>35</b><span>Focused chapters</span></div><div><b>53</b><span>Source pages</span></div><div><b>01</b><span>Practical guide</span></div></div><div class="notice"><span>↳</span><div><b>A living tool. A version-dependent guide.</b>Claude Code changes quickly. Type <code>/</code> in your session to see what’s available. This website preserves the supplied PDF; it is not a live command reference.</div></div></section><div class="section-head"><h2>A good place to begin</h2><span>THE FOUNDATIONS</span></div><div class="cards">${[0,1,2,5,9,31].map(card).join('')}</div><div class="terminal"><div class="terminal-label">YOUR FIRST SESSION</div><code><span>$</span> claude</code><p style="font-size:12px;color:#a4b2a3;margin-bottom:0">Start in your project. Give it one focused task. Build from there.</p></div><div class="section-head"><h2>The complete field guide</h2><span>EXPLORE ALL 35 CHAPTERS</span></div><div class="cards">${guide.map((_,i)=>card(i)).join('')}</div>${foot}`;nav()}
function format(t){return t.split('\n').map(line=>{const v=line.trim();return /^(claude(?:\s|$)|\/(?:[a-z][a-z-]*)(?:\s|$)|![a-z]|tail -n|isolation: worktree)/.test(v)?`<div class="command-line"><code>${esc(v)}</code><button class="copy" data-copy="${esc(v)}" aria-label="Copy command">Copy</button></div>`:esc(line)+'\n'}).join('')}
function chapter(i){const c=guide[i];if(!c){home();return}current=i;$('#main').innerHTML=`<article class="chapter"><div class="chapter-top"><a href="#home">← Back to overview</a><span>CHAPTER ${String(i+1).padStart(2,'0')} / ${guide.length}</span></div><h1>${esc(c.title)}</h1><p class="lead">${esc(c.description)}</p><button class="read-button ${completed.includes(i)?'done':''}" id="complete">${completed.includes(i)?'✓ Completed':'Mark as read'}</button>${c.pages.map(p=>`<section class="source-page"><div class="page-label"><span>FROM THE GUIDE · PAGE ${p.number}</span><a href="Claude_Code_Guide.pdf#page=${p.number}" target="_blank" rel="noopener">VIEW ORIGINAL ↗</a></div><div class="source-text">${format(p.text)}</div></section>`).join('')}<div class="chapter-bottom">${i>0?`<a href="#chapter-${i}"><small>← PREVIOUS</small>${esc(guide[i-1].title)}</a>`:'<span></span>'}${i<guide.length-1?`<a href="#chapter-${i+2}" style="text-align:right"><small>NEXT →</small>${esc(guide[i+1].title)}</a>`:'<a href="#home">Back to overview →</a>'}</div>${foot}</article>`;$('#complete').onclick=()=>{completed=completed.includes(i)?completed.filter(n=>n!==i):[...completed,i];try{localStorage.setItem('guide-completed',JSON.stringify(completed))}catch{}chapter(i)};nav()}
function search(q){current=-1;const results=guide.map((c,i)=>({c,i,body:c.pages.map(p=>p.text).join(' ')})).filter(({c,body})=>(c.title+' '+c.description+' '+body).toLowerCase().includes(q.toLowerCase()));$('#main').innerHTML=`<section class="search-results"><div class="kicker">SEARCH THE FIELD GUIDE</div><h1>Find your next step.</h1><p class="lead">${results.length} chapter${results.length===1?'':'s'} matching “${esc(q)}”</p>${results.length?results.map(({c,i,body})=>{const at=body.toLowerCase().indexOf(q.toLowerCase());const snippet=at>=0?body.slice(Math.max(0,at-65),at+160):c.description;return `<a class="result" href="#chapter-${i+1}"><span class="eyebrow">CHAPTER ${i+1} · PAGE ${c.start}</span><br><strong>${esc(c.title)} →</strong><p>${at>65?'…':''}${esc(snippet)}…</p></a>`}).join(''):'<p class="empty">No matching chapters. Try “permissions”, “worktree”, or “/compact”.</p>'}</section>`;nav()}
function route(){query='';$('#search').value='';const m=location.hash.match(/^#chapter-(\d+)$/);if(m)chapter(Number(m[1])-1);else home();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');window.scrollTo(0,0)}
$('#search').addEventListener('input',e=>{query=e.target.value.trim();if(query)search(query);else route()});$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('guide-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();$('#sidebar').classList.add('open');$('#menu').setAttribute('aria-expanded','true');$('#search').focus()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#search').blur()}});document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>{b.textContent='Copy'},1500)}catch{b.textContent='Select to copy';const r=document.createRange();r.selectNodeContents(b.previousElementSibling);getSelection().removeAllRanges();getSelection().addRange(r)}});window.addEventListener('hashchange',route);fetch('guide.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{guide=d;route()}).catch(()=>{$('#main').innerHTML='<h1>Guide unavailable</h1><p>Please reload the page or <a href="Claude_Code_Guide.pdf">open the original PDF</a>.</p>'});
document.addEventListener("click", e => { const a=e.target.closest("a"); if(a && a.hash.startsWith("#chapter-") && a.hash===location.hash && query) route(); });
